questions.solution:
def gamma(d, u):
    """gamma_d = d * u / (1 - d * u)."""
    return d * u / (1 - d * u)


def within(result, ref, xs, d, u):
    """True when |result - ref| <= gamma_d * sum(|x| for x in xs)."""
    return abs(result - ref) <= gamma(d, u) * sum(abs(x) for x in xs)
